create table if not exists public.accounts_payable_entries(id uuid primary key default gen_random_uuid(),vendor_bill_id uuid not null unique references public.vendor_bill_drafts(id) on delete cascade,purchase_order_id uuid references public.purchase_orders(id) on delete set null,supplier_id uuid references public.suppliers(id) on delete set null,customer_id uuid references public.customers(id) on delete set null,invoice_number text,invoice_date date,due_date date,materials_cogs numeric not null default 0,tax numeric not null default 0,total numeric not null default 0,status text not null default 'open' check(status in ('open','paid','void')),posted_by uuid references public.users(id),posted_at timestamptz not null default now(),created_at timestamptz not null default now());alter table public.accounts_payable_entries enable row level security;create policy "finance read ap entries" on public.accounts_payable_entries for select to authenticated using(private.current_employee_role() in ('owner','manager','accounting'));create policy "finance manage ap entries" on public.accounts_payable_entries for all to authenticated using(private.current_employee_role() in ('owner','manager','accounting')) with check(private.current_employee_role() in ('owner','manager','accounting'));
create or replace function public.review_and_approve_vendor_bill(p_bill_id uuid,p_invoice_number text,p_invoice_date date,p_due_date date,p_subtotal numeric,p_tax numeric,p_total numeric,p_account_code text,p_memo text) returns uuid language plpgsql security definer set search_path=public as $$ declare v_user public.users%rowtype;v_bill public.vendor_bill_drafts%rowtype;begin select * into v_user from public.users where auth_user_id=auth.uid() and active=true limit 1;if v_user.id is null or v_user.role not in ('owner','manager','accounting') then raise exception 'not authorized';end if;if coalesce(p_total,0)<=0 then raise exception 'bill total must be positive';end if;if coalesce(p_subtotal,0)<0 or coalesce(p_tax,0)<0 then raise exception 'invalid amounts';end if;if abs((coalesce(p_subtotal,0)+coalesce(p_tax,0))-p_total)>0.05 then raise exception 'subtotal plus tax must equal total';end if;select * into v_bill from public.vendor_bill_drafts where id=p_bill_id for update;if v_bill.id is null then raise exception 'bill not found';end if;update public.vendor_bill_drafts set invoice_number=nullif(trim(p_invoice_number),''),invoice_date=p_invoice_date,due_date=p_due_date,subtotal=p_subtotal,tax=p_tax,total=p_total,account_code=coalesce(nullif(trim(p_account_code),''),'materials_cogs'),memo=nullif(trim(p_memo),''),status='approved',approved_by=v_user.id,approved_at=now(),updated_at=now() where id=p_bill_id;insert into public.accounts_payable_entries(vendor_bill_id,purchase_order_id,supplier_id,customer_id,invoice_number,invoice_date,due_date,materials_cogs,tax,total,posted_by) values(p_bill_id,v_bill.purchase_order_id,v_bill.supplier_id,v_bill.customer_id,nullif(trim(p_invoice_number),''),p_invoice_date,p_due_date,p_subtotal,p_tax,p_total,v_user.id) on conflict(vendor_bill_id) do update set invoice_number=excluded.invoice_number,invoice_date=excluded.invoice_date,due_date=excluded.due_date,materials_cogs=excluded.materials_cogs,tax=excluded.tax,total=excluded.total,posted_by=excluded.posted_by,posted_at=now();update public.purchase_order_documents set analysis_status='reviewed' where id=v_bill.document_id;insert into public.audit_log(actor_user_id,action,entity_type,entity_id,after_data) values(v_user.id,'approve_vendor_bill','vendor_bill',p_bill_id,jsonb_build_object('total',p_total,'invoice_number',p_invoice_number,'account_code',p_account_code));return p_bill_id;end$$;revoke all on function public.review_and_approve_vendor_bill(uuid,text,date,date,numeric,numeric,numeric,text,text) from public,anon;grant execute on function public.review_and_approve_vendor_bill(uuid,text,date,date,numeric,numeric,numeric,text,text) to authenticated;
